"

mkdir -p /tmp/fb_scripts && cat > /tmp/fb_scripts/summ.py <<'EOF'
import json,sys
d=json.load(open(sys.argv[1]))
for a in d['customers']:
  s=a['services']; out=['== %s %s %s'%(a['customerNo'],a['firstName'],a['lastName'])]
  cl=s.get('cards.list')
  if cl['http']!=200: out.append(' list %s %s'%(cl['http'],cl['response']['result']['code']))
  else: out.append(' list '+'; '.join('%s|%s|%s'%(c['cardNumber'][-10:],c['productName'],'M' if c['isMainCard'] else 'S') for c in cl['response']['data']['cards']))
  if cl.get('delaySeconds'): out.append(' LIST DELAY %s'%cl['delaySeconds'])
  for cn,b in s.get('cards.balance',{}).items():
    if b.get('delaySeconds'): out.append(' BAL DELAY %s %s'%(cn,b['delaySeconds']))
    if b['http']!=200: out.append(' bal %s %s %s'%(cn[-6:],b['http'],b['response']['result']['code'])); continue
    x=b['response']['data']
    parts=[]
    for k in ('debtTL','debtUSD','debtEUR','debtGBP'):
      v=x.get(k)
      if v is None: parts.append(k[4:]+':-'); continue
      parts.append('%s:%s/%s/%s/%s/td%s%s%s'%(k[4:],v.get('statementDebt'),v.get('minPayment'),v.get('remainingDebt'),v.get('remainingMinPayment'),v.get('totalDebt'),' TR%s'%v['transferAmount'] if v.get('transferAmount') else '',' RA%s'%v['remainAutomaticPaymentAmount'] if v.get('remainAutomaticPaymentAmount') else ''))
    out.append(' bal %s st=%s due=%s nst=%s ndue=%s %s ap=%s | %s'%(cn[-4:],x.get('statementDate'),x.get('lastPayDate'),x.get('nextStatementDate'),x.get('nextLastPayDate'),x.get('statementPaymentStatus'),x.get('automaticPaymentFlag'),' '.join(parts)))
  for cn,b in s.get('statement.week.get',{}).items():
    if b['http']!=200: out.append(' wk %s %s'%(cn[-4:],b['http'])); continue
    x=b['response']['data']
    if x['relationType'] or True: out.append(' wk %s w%s d%s %s %s rel=%r %s %s'%(cn[-4:],x['statementWeek'],x['statementDay'],x['nextStatementDate'],x['nextLastPayDate'],x['relationType'],x['relatedCardNumber'][-4:],x['relatedCardProductName']))
  for cn,ws in s.get('statement.week.decide',{}).items():
    bad={w:v['http'] for w,v in ws.items() if v['http']!=200}
    out.append(' dec %s weeks=%s %s'%(cn[-4:],sorted(ws),('BAD %s'%bad) if bad else ''))
  for cn,ws in s.get('statement.week.change',{}).items():
    bad={w:(v['http'],v['response'].get('result',{}).get('code'),v['response'].get('data',{}).get('exitState')) for w,v in ws.items() if v['http']!=200 or v['response'].get('data',{}).get('exitState')!='OK'}
    if bad: out.append(' chg %s BAD %s'%(cn[-4:],bad))
  e=s.get('contact.email.get')
  if e: out.append(' mail %s %s %s'%(e['http'],e['response'].get('data',{}).get('ibanEmail'),e['response'].get('data',{}).get('communicationType')))
  p=s.get('statement.pdf.send'); out.append(' pdf %s'%((p['http'], p['response']['result']['code']) if p else None))
  print('\n'.join(out))
EOF
