def code_node(name, body, routes, fallback, tts=""):
    """A passthrough code node. body sets vars['r_<name>']; routes = [(value, target)]."""
    rv = "r_" + name
    src = HELP + "\n\ndef main():\n" + textwrap.indent(textwrap.dedent(body).strip("\n"), "    ") + \
        "\n\ntry:\n    vars['%s'] = 'error'\n    main()\nexcept Exception as e:\n    vars['%s'] = 'error'\n    vars['last_error'] = str(e)[:200]\n" % (rv, rv)
    assert "{{" not in src and "}}" not in src, name
    trans = [{"target_node": t, "description": "%s = %s" % (rv, v),
              "condition": {"logic": "or", "conditions": [{"variable": rv, "operator": "equals", "operand": v}]}}
             for v, t in routes]
    trans.append({"target_node": fallback, "description": "always", "condition": {"operator": "always"}})
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": fallback,
        "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"},
        "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                         "parameters": {"type": "object", "properties": {
                             "code": {"type": "string", "default": src},
                             "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": trans,
    }


def post_hook(nf, nf404):
    src = textwrap.dedent('''
    try:
        import json
        sc = None
        body = None
        if isinstance(result, dict):
            sc = result.get('status_code')
            body = result.get('data')
            result.pop('header', None)
        if isinstance(body, str):
            try:
                body = json.loads(body)
            except Exception:
                pass
        st = 'error'
        inner = None
        if isinstance(body, dict):
            r = body.get('result')
            if not isinstance(r, dict):
                r = dict()
            code = str(r.get('code') or r.get('returnCode') or '')
            if code == '1' and isinstance(body.get('data'), dict) and str(sc) in ('200', 'None', ''):
                st = 'ok'
                inner = body.get('data')
            elif code in NF:
                st = 'notfound'
        if st == 'error' and str(sc) == '404' and NF404:
            st = 'notfound'
        if isinstance(result, dict):
            result['data'] = dict(fb_state=st, fb_body=(json.dumps(inner, ensure_ascii=False) if inner is not None else ''))
    except Exception:
        pass
    ''').replace("NF404", "True" if nf404 else "False").replace("NF", json.dumps(nf))
    assert "{{" not in src and "}}" not in src
    return src


def api_node(name, service, key, data_fields, pre_body, nf, nf404, nxt, tts="", timeout=25000):
    """A passthrough api_request node calling <mock>/voice/v1/<service> with the contract envelope."""
    data_props = {f: {"type": "string", "default": d} for f, d in data_fields.items()}
    pre = "try:\n    config['body'] = dict(data=dict(%s), call=dict(ani='', lang='tr'))\nexcept Exception:\n    pass\n" % pre_body
    assert "{{" not in pre and "}}" not in pre
    return {
        "name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"},
        "disable_inactivity_monitor": True, "suppress_tool_results": True,
        "pre_actions": [{
            "type": "function", "config": {"timeoutMs": timeout, "maxRetries": 0},
            "function": {
                "name": service.replace(".", "_"), "handler": "__function__:api_call",
                "description": "Freya Bank %s service." % service,
                "parameters": {"type": "object", "properties": {
                    "url": {"type": "string", "default": BASE + PATH + service},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {
                        "Content-Type": {"type": "string", "default": "application/json"},
                        "Accept": {"type": "string", "default": "application/json"},
                        "Authorization": {"type": "string", "default": "Bearer voice-statement-test"}}},
                    "body": {"type": "object", "properties": {
                        "data": {"type": "object", "properties": data_props},
                        "call": {"type": "object", "properties": {
                            "ani": {"type": "string", "default": ""},
                            "lang": {"type": "string", "default": "tr"}}}}}}}},
            "pre_process_code": pre,
            "post_process_code": post_hook(nf, nf404),
        }],
        "response_mapping": [
            {"path": "data.fb_state", "variable": key + "_state"},
            {"path": "data.fb_body", "variable": key + "_body"},
            {"path": "data.data", "variable": key + "_raw"},
            {"path": "data.result.code", "variable": key + "_code"},
        ],
        "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


