def listen_node(name, tts_var, task, enum_var, enum_values, enum_desc, route_values, route_node, extra_schema=None):
    schema = [{"name": enum_var, "type": "string", "enum_values": enum_values, "description": enum_desc,
               "min_confidence": 0.6}] + (extra_schema or [])
    return {
        "name": name, "node_type": "conversation",
        "on_enter": {"type": "tts", "text": "{{%s}}" % tts_var},
        "task_message": task + "\n\n" + NO_TOOL,
        "extraction_schema": schema,
        "max_node_turns": 30, "max_turn_transition": "end_tries",
        "transitions": [{"target_node": route_node, "description": "%s is %s" % (enum_var, "/".join(route_values)),
                         "condition": {"logic": "or", "conditions": [
                             {"variable": enum_var, "operator": "equals", "operand": v} for v in route_values]}}],
    }


def end_node(name, farewell):
    body = "vars['farewell'] = %r\nvars['r_%s'] = 'end'\n" % (farewell, name)
    return code_node(name, body, [("end", "goodbye")], "goodbye")


