# ------------------------------------------------------------------ shared Python for code nodes (no brace pairs)
HELP = r'''
import json, re, datetime
MONTHS = ['', 'Ocak', 'Şubat', 'Mart', 'Nisan', 'Mayıs', 'Haziran', 'Temmuz', 'Ağustos', 'Eylül', 'Ekim', 'Kasım', 'Aralık']
ONES = ['', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
TENS = ['', 'on', 'yirmi', 'otuz', 'kırk', 'elli', 'altmış', 'yetmiş', 'seksen', 'doksan']
DIG = ['sıfır', 'bir', 'iki', 'üç', 'dört', 'beş', 'altı', 'yedi', 'sekiz', 'dokuz']
CUR_NAME = dict(TL='Türk Lirası', USD='Dolar', EUR='Euro', GBP='İngiliz Sterlini')
UNITS = dict(TL=('Türk Lirası', 'lira', 'kuruş'), USD=('dolar', 'dolar', 'sent'), EUR=('Euro', 'Euro', 'sent'), GBP=('İngiliz Sterlini', 'İngiliz Sterlini', 'peni'))
CURS = ['TL', 'USD', 'EUR', 'GBP']
MENU = 'Sizi ana menüye yönlendiriyorum.'
FAIL_TRIES = 'Size şu anda yardımcı olamıyorum. Sizi ana menüye aktarıyorum.'
FAIL_SVC = 'Şu anda işleminizi gerçekleştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'
FAIL_WEEK = 'Şu anda hesap kesim tarihinizi değiştiremiyorum, sizi müşteri temsilcimize aktarıyorum.'

def w3(n):
    out = []
    h, r = divmod(n, 100)
    if h:
        out.append('yüz' if h == 1 else ONES[h] + ' yüz')
    t, o = divmod(r, 10)
    if t:
        out.append(TENS[t])
    if o:
        out.append(ONES[o])
    return ' '.join(out)

def words(n):
    n = int(n)
    if n == 0:
        return 'sıfır'
    parts = []
    for val, name in ((1000000000, 'milyar'), (1000000, 'milyon'), (1000, 'bin')):
        q, n = divmod(n, val)
        if q:
            parts.append('bin' if (val == 1000 and q == 1) else words(q) + ' ' + name)
    if n:
        parts.append(w3(n))
    return ' '.join(parts)

def num(x):
    try:
        return float(x)
    except Exception:
        return 0.0

def say_amt(x, cur):
    c = int(round(abs(num(x)) * 100))
    whole, frac = c // 100, c % 100
    full, unit, sub = UNITS[cur]
    if frac:
        return words(whole) + ' ' + unit + ' ' + words(frac) + ' ' + sub
    return words(whole) + ' ' + full

def suffix(phrase):
    last = phrase.strip().split(' ')[-1]
    low = last.replace('İ', 'i').replace('I', 'ı').lower()
    vow = [ch for ch in low if ch in 'aeıioöuü']
    v = vow[-1] if vow else 'e'
    hv = dict(a='ı', ı='ı', e='i', i='i', o='u', u='u', ö='ü', ü='ü')[v]
    return ('t' if low[-1:] in 'fstkçşhp' else 'd') + hv + 'r'

def cop(phrase):
    last = phrase.strip().split(' ')[-1]
    if last[:1].isupper():
        return phrase + "'" + suffix(phrase)
    return phrase + suffix(phrase)

def pdate(s):
    try:
        d, m, y = str(s).strip().split('.')
        return datetime.date(int(y), int(m), int(d))
    except Exception:
        return None

def say_date(dt):
    return '%d %s %d' % (dt.day, MONTHS[dt.month], dt.year)

def date_cop(dt):
    return say_date(dt) + "'" + suffix(words(dt.year))

def today_of():
    m = re.match(r'(\d{4})-(\d{2})-(\d{2})', str(vars.get('now') or ''))
    if m:
        return datetime.date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
    return None

def say_digits(s):
    return ' '.join(DIG[int(c)] for c in str(s) if c.isdigit())

def jl(x):
    if isinstance(x, (dict, list)):
        return x
    try:
        return json.loads(str(x))
    except Exception:
        return None

def good_name(n):
    n = str(n or '').strip()
    if n and len(n) <= 32 and len(n.split()) <= 4 and not re.search(r'talimat|instruction|numara|oku', n, re.I):
        return n
    return ''

def card_label(c):
    n = good_name(c[2])
    if n:
        return n
    return 'sonu ' + say_digits(c[1]) + ' ile biten kartınız'

def intro(last4, name):
    if good_name(name):
        return 'Sonu ' + say_digits(last4) + ' ile biten ' + good_name(name) + ' kartınız'
    return 'Sonu ' + say_digits(last4) + ' ile biten kartınız'

def join_tr(items):
    items = [i for i in items if i]
    if len(items) <= 1:
        return ''.join(items)
    return ', '.join(items[:-1]) + ' ve ' + items[-1]

def svc_state(key, tool, nf):
    st = str(vars.get(key + '_state') or '')
    body = jl(vars.get(key + '_body'))
    if st == 'ok' and isinstance(body, dict):
        return 'ok', body
    if st == 'notfound':
        return 'notfound', None
    if st == '':
        code = str(vars.get(key + '_code') or '')
        raw = jl(vars.get(key + '_raw'))
        if code == '1' and isinstance(raw, dict):
            return 'ok', raw
        if code in nf:
            return 'notfound', None
        for k in list(vars.keys()):
            if str(k).startswith(tool + '_'):
                val = str(vars.get(k))
                for c in nf:
                    if c in val:
                        return 'notfound', None
    return 'error', None

def clear_svc(key):
    for s in ('_state', '_body', '_code', '_raw'):
        vars[key + s] = ''

def cards():
    return jl(vars.get('cards_json')) or []

def elig():
    return [c for c in cards() if c[3] == 'M']

def unread():
    done = jl(vars.get('read_cards')) or []
    return [c for c in elig() if c[0] not in done]

def ask_card_q(pool):
    names = []
    for c in pool:
        n = good_name(c[2])
        if n and n not in names:
            names.append(n)
    if len(names) >= 2:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' veya ' + names[1] + ' diyebilirsiniz.'
    if len(names) == 1:
        return 'Hangi kartınızın borcunu öğrenmek istersiniz? Örneğin, ' + names[0] + ' diyebilirsiniz.'
    return 'Hangi kartınızın borcunu öğrenmek istersiniz? Kartınızın son dört hanesini söyleyebilirsiniz.'

def all_names_text():
    labels = []
    for c in elig():
        lab = card_label(c)
        if lab not in labels:
            labels.append(lab)
    return 'Kartlarınız: ' + join_tr(labels) + '.'

def start_select(pool):
    vars['sel_stage'] = 'name'
    vars['cand'] = '[]'
    vars['tries'] = 0
    q = ask_card_q(pool or elig())
    vars['stage_q'] = q
    vars['select_msg'] = q

def choose(c):
    vars['sel_card'] = c[0]
    vars['sel_last4'] = c[1]
    vars['sel_name'] = good_name(c[2])
    vars['sel_stage'] = 'name'
    vars['cand'] = '[]'
    vars['tries'] = 0
    clear_svc('bal')
'''


def code_node(name, body, routes, fallback, tts=""):
    """A passthrough code node. body sets vars['r_<name>']; routes = [(value, target)]."""
    rv = "r_" + name
    src = HELP + "\n\ndef main():\n" + textwrap.indent(textwrap.dedent(body).strip("\n"), "    ") + \
        "\n\ntry:\n    vars['%s'] = 'error'\n    main()\nexcept Exception as e:\n    vars['%s'] = 'error'\n    vars['last_error'] = str(e)[:200]\n" % (rv, rv)
    assert "{{" not in src and "}}" not in src, name
    trans = [{"target_node": t, "description": "%s = %s" % (rv, v),
              "condition": {"logic": "or", "conditions": [{"variable": rv, "operator": "equals", "operand": v}]}}
             for v, t in routes]
    trans.append({"target_node": fallback, "description": "always", "condition": {"operator": "always"}})
    return {
        "name": name, "node_type": "code", "passthrough": True, "passthrough_default_transition": fallback,
        "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"},
        "disable_inactivity_monitor": True,
        "pre_actions": [{"type": "function", "function": {"name": "code_exec", "handler": "__function__:code_exec",
                         "parameters": {"type": "object", "properties": {
                             "code": {"type": "string", "default": src},
                             "timeout_ms": {"type": "number", "default": 10000}}}}}],
        "transitions": trans,
    }


def post_hook(nf, nf404):
    src = textwrap.dedent('''
    try:
        import json
        sc = None
        body = None
        if isinstance(result, dict):
            sc = result.get('status_code')
            body = result.get('data')
            result.pop('header', None)
        if isinstance(body, str):
            try:
                body = json.loads(body)
            except Exception:
                pass
        st = 'error'
        inner = None
        if isinstance(body, dict):
            r = body.get('result')
            if not isinstance(r, dict):
                r = dict()
            code = str(r.get('code') or r.get('returnCode') or '')
            if code == '1' and isinstance(body.get('data'), dict) and str(sc) in ('200', 'None', ''):
                st = 'ok'
                inner = body.get('data')
            elif code in NF:
                st = 'notfound'
        if st == 'error' and str(sc) == '404' and NF404:
            st = 'notfound'
        if isinstance(result, dict):
            result['data'] = dict(fb_state=st, fb_body=(json.dumps(inner, ensure_ascii=False) if inner is not None else ''))
    except Exception:
        pass
    ''').replace("NF404", "True" if nf404 else "False").replace("NF", json.dumps(nf))
    assert "{{" not in src and "}}" not in src
    return src


def api_node(name, service, key, data_fields, pre_body, nf, nf404, nxt, tts="", timeout=25000):
    """A passthrough api_request node calling <mock>/voice/v1/<service> with the contract envelope."""
    data_props = {f: {"type": "string", "default": d} for f, d in data_fields.items()}
    pre = "try:\n    config['body'] = dict(data=dict(%s), call=dict(ani='', lang='tr'))\nexcept Exception:\n    pass\n" % pre_body
    assert "{{" not in pre and "}}" not in pre
    return {
        "name": name, "node_type": "api_request", "passthrough": True, "passthrough_default_transition": nxt,
        "on_enter": {"type": "tts", "text": tts} if tts else {"type": "silent"},
        "disable_inactivity_monitor": True, "suppress_tool_results": True,
        "pre_actions": [{
            "type": "function", "config": {"timeoutMs": timeout, "maxRetries": 0},
            "function": {
                "name": service.replace(".", "_"), "handler": "__function__:api_call",
                "description": "Freya Bank %s service." % service,
                "parameters": {"type": "object", "properties": {
                    "url": {"type": "string", "default": BASE + PATH + service},
                    "method": {"type": "string", "default": "POST"},
                    "headers": {"type": "object", "properties": {
                        "Content-Type": {"type": "string", "default": "application/json"},
                        "Accept": {"type": "string", "default": "application/json"},
                        "Authorization": {"type": "string", "default": "Bearer voice-statement-test"}}},
                    "body": {"type": "object", "properties": {
                        "data": {"type": "object", "properties": data_props},
                        "call": {"type": "object", "properties": {
                            "ani": {"type": "string", "default": ""},
                            "lang": {"type": "string", "default": "tr"}}}}}}}},
            "pre_process_code": pre,
            "post_process_code": post_hook(nf, nf404),
        }],
        "response_mapping": [
            {"path": "data.fb_state", "variable": key + "_state"},
            {"path": "data.fb_body", "variable": key + "_body"},
            {"path": "data.data", "variable": key + "_raw"},
            {"path": "data.result.code", "variable": key + "_code"},
        ],
        "transitions": [{"target_node": nxt, "description": "always", "condition": {"operator": "always"}}],
    }


